# region: intake
def intake(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: fold
def fold(xs, limit=5):
    return [v if v <= limit else limit for v in xs]

# region: digest
def digest(xs, offset=-1):
    return [v + offset for v in xs]

# region: emit
def emit(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (min(xs) - min(xs)) if xs else 0}

# region: sift
def sift(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return sift(emit(digest(fold(intake(raw)))))

